import pandas as pd
import sqlite3

def task_func(db_path: str, table_name: str, column_name: str) -> pd.DataFrame:
    def quote_identifier(name: str) -> str:
        return '"' + name.replace('"', '""') + '"'

    conn = sqlite3.connect(db_path)
    try:
        df = pd.read_sql_query(f"SELECT * FROM {quote_identifier(table_name)}", conn)
    finally:
        conn.close()

    df[column_name] = df[column_name].apply(
        lambda value: value.replace("\n", "<br>") if isinstance(value, str) else value
    )
    return df
